using MessagePack;
using MessagePack.Formatters;

public class ProbeNonPublicHolder
{
    public int PublicValue { get; set; }

    private int hidden;

    public void SetHidden(int value) => this.hidden = value;

    public int GetHidden() => this.hidden;
}

[GeneratedMessagePackFormatter(IncludeNonPublicMembers = true)]
public partial class ProbeNonPublicHolderFormatter : IMessagePackFormatter<ProbeNonPublicHolder>
{
}

public class ProbeIncludeNonPublicMembersTests
{
    private static readonly MessagePackSerializerOptions Options = MessagePackSerializerOptions.Standard
        .WithResolver(CompositeResolver.Create(GeneratedMessagePackResolver.Instance, StandardResolver.Instance));

    [Fact]
    public void IncludeNonPublicMembersTrueSerializesPrivateField()
    {
        var holder = new ProbeNonPublicHolder { PublicValue = 3 };
        holder.SetHidden(42);

        byte[] bytes = MessagePackSerializer.Serialize(holder, Options);
        ProbeNonPublicHolder result = MessagePackSerializer.Deserialize<ProbeNonPublicHolder>(bytes, Options);

        Assert.Equal(3, result.PublicValue);
        // With IncludeNonPublicMembers = true the private member is expected to be part of the contract.
        Assert.Equal(42, result.GetHidden());
    }
}
